164: async function runSuite(suite, verbose = false) {
165:   const fullPath = path.join(ROOT_DIR, suite.path);
166:   if (!fs.existsSync(fullPath)) {
167:     return {
168:       id: suite.id,
169:       name: suite.name,
170:       tier: suite.tier,
171:       pass: false,
172:       error: `File not found: ${suite.path}`,
173:       checks: 0,
174:       passedChecks: 0,
175:       failedChecks: 1,
176:       duration: 0
177:     };
178:   }
179: 
180:   return new Promise((resolve) => {
181:     const startTime = Date.now();
182:     const child = spawn('node', [suite.path], {
183:       cwd: ROOT_DIR,
184:       env: { ...process.env, FORCE_COLOR: '1' }
185:     });
186: 
187:     let stdout = '';
188:     let stderr = '';
189: 
190:     child.stdout.on('data', chunk => {
191:       stdout += chunk;
192:       if (verbose) process.stdout.write(chunk);
193:     });
194: 
195:     child.stderr.on('data', chunk => {
196:       stderr += chunk;
197:       if (verbose) process.stderr.write(chunk);
198:     });
199: 
200:     child.on('close', (code) => {
201:       const duration = Date.now() - startTime;
202:       const counts = extractCheckCounts(stdout, suite.minChecks);
203:       const isSuccess = code === 0 && counts.failed === 0;
204: 
205:       resolve({
206:         id: suite.id,
207:         name: suite.name,
208:         path: suite.path,
209:         tier: suite.tier,
210:         milestone: suite.milestone,
211:         pass: isSuccess,
212:         exitCode: code,
213:         passedChecks: isSuccess ? Math.max(counts.passed, suite.minChecks) : counts.passed,
214:         failedChecks: counts.failed + (code !== 0 && counts.failed === 0 ? 1 : 0),
215:         duration,
216:         stdout,
217:         stderr
218:       });
219:     });
220:   });
221: }
